def bigger(a, b):
    if a > b:
        return a
    return b

def smaller(a, b):
    if a < b:
        return a
    return b

def total_points(points):
    total = 0
    for point in points:
        total += point
    return total

def clamp_x(x, max_x):
    if x < 0:
        return 0
    if x > max_x:
        return max_x
    return x
